diff --git a/src/main/java/org/jsoup/Jsoup.java b/src/main/java/org/jsoup/Jsoup.java
index d25c1869..13392e8a 100644
--- a/src/main/java/org/jsoup/Jsoup.java
+++ b/src/main/java/org/jsoup/Jsoup.java
@@ -1,6 +1,9 @@
 package org.jsoup;

 import org.jsoup.nodes.Document;
+import org.jsoup.nodes.Element;
+import org.jsoup.nodes.Node;
+import org.jsoup.parser.ParseErrorList;
 import org.jsoup.parser.Parser;
 import org.jsoup.safety.Cleaner;
 import org.jsoup.safety.Whitelist;
@@ -247,7 +250,14 @@ public class Jsoup {
      @see #clean(String, org.jsoup.safety.Whitelist) 
      */
     public static boolean isValid(String bodyHtml, Whitelist whitelist) {
-        return new Cleaner(whitelist).isValid(parseBodyFragment(bodyHtml, ""));
+        ParseErrorList errors = ParseErrorList.tracking(1);
+        Document doc = Document.createShell("");
+        Element body = doc.body();
+        Node[] nodes = Parser.parseFragment(bodyHtml, body, "", errors).toArray(new Node[0]);
+        if (errors.size() > 0) return false;
+        for (int i = nodes.length - 1; i > 0; i--) nodes[i].remove();
+        for (Node node : nodes) body.appendChild(node);
+        return new Cleaner(whitelist).isValid(doc);
     }

 }
